Instead of inserting the whole array first, this code inserts one number and queries it against the numbers already seen. A number never needs to pair with itself, and every pair is considered when its second value is processed.

At each trie level, the opposite branch is preferred. The empty and one-element cases naturally return `0` because there is no pair to improve the answer.

```java
class Solution {
    private static class Node {
        Node[] next = new Node[2];
    }

    private void insert(Node root, int value) {
        Node current = root;

        for (int bit = 30; bit >= 0; --bit) {
            int valueBit = (value >> bit) & 1;
            if (current.next[valueBit] == null) {
                current.next[valueBit] = new Node();
            }
            current = current.next[valueBit];
        }
    }

    private int query(Node root, int value) {
        Node current = root;
        int result = 0;

        for (int bit = 30; bit >= 0; --bit) {
            int valueBit = (value >> bit) & 1;
            int opposite = valueBit ^ 1;

            if (current.next[opposite] != null) {
                result |= (1 << bit);
                current = current.next[opposite];
            } else {
                current = current.next[valueBit];
            }
        }

        return result;
    }

    public int findMaximumXOR(int[] nums) {
        if (nums.length < 2) {
            return 0;
        }

        Node root = new Node();
        insert(root, nums[0]);
        int answer = 0;

        for (int index = 1; index < nums.length; ++index) {
            answer = Math.max(answer, query(root, nums[index]));
            insert(root, nums[index]);
        }

        return answer;
    }
}
```

Dry run with `[2, 7, 4]`: insert `2`, then query `7` to get `5`. After inserting `7`, querying `4` can find `7`, giving `3`, so the final answer is `5`.

Time complexity: each value is inserted and queried through 31 bits, so the total is `O(31 * n)`. Space complexity: `O(31 * n)` for the nodes.

Numbers can be split into groups by their current bit. A pair from different groups gets a `1` at that bit, which is better than any result with a `0` there. The helper keeps only opposite groups when that is possible, then continues with the next lower bit.

This avoids a trie, but it creates temporary vectors during the recursion. The array itself is not changed.

```cpp
class Solution {
private:
    int bestAcross(const vector<int>& zeros, const vector<int>& ones, int bit) {
        if (zeros.empty() || ones.empty() || bit < 0) {
            return 0;
        }

        vector<int> zeroLeft;
        vector<int> zeroRight;
        vector<int> oneLeft;
        vector<int> oneRight;

        for (int value : zeros) {
            if (((value >> bit) & 1) == 0) {
                zeroLeft.push_back(value);
            } else {
                zeroRight.push_back(value);
            }
        }

        for (int value : ones) {
            if (((value >> bit) & 1) == 0) {
                oneLeft.push_back(value);
            } else {
                oneRight.push_back(value);
            }
        }

        int answer = 0;
        if (!zeroLeft.empty() && !oneRight.empty()) {
            answer = max(answer, (1 << bit) + bestAcross(zeroLeft, oneRight, bit - 1));
        }
        if (!zeroRight.empty() && !oneLeft.empty()) {
            answer = max(answer, (1 << bit) + bestAcross(zeroRight, oneLeft, bit - 1));
        }

        if (answer != 0) {
            return answer;
        }

        return max(bestAcross(zeros, ones, bit - 1), 0);
    }

    int solveGroup(const vector<int>& values, int bit) {
        if (values.size() < 2 || bit < 0) {
            return 0;
        }

        vector<int> zeros;
        vector<int> ones;

        for (int value : values) {
            if (((value >> bit) & 1) == 0) {
                zeros.push_back(value);
            } else {
                ones.push_back(value);
            }
        }

        int answer = bestAcross(zeros, ones, bit - 1);
        answer = max(answer, solveGroup(zeros, bit - 1));
        answer = max(answer, solveGroup(ones, bit - 1));
        return answer;
    }

public:
    int findMaximumXOR(vector<int>& nums) {
        if (nums.size() < 2) {
            return 0;
        }
        return solveGroup(nums, 30);
    }
};
```

The base cases cover arrays with fewer than two values and the point where there are no lower bits left. The recursive grouping is based on the highest bit first, so a lower bit cannot undo a better higher-bit choice.

Time complexity: `O(31 * n)` in the fixed integer range. Space complexity: `O(31 * n)` from recursion and temporary groups.

This version builds the answer one bit at a time instead of storing a trie. At each bit, all current prefixes are placed in a set. Then the code checks whether two prefixes can create the candidate answer.

If `a ^ b = candidate`, then `b = a ^ candidate`. That is why checking `candidate ^ prefix` in the set tells us whether the bit can stay set.

```java
class Solution {
    public int findMaximumXOR(int[] nums) {
        int answer = 0;
        int mask = 0;

        for (int bit = 30; bit >= 0; --bit) {
            mask |= (1 << bit);

            java.util.HashSet<Integer> prefixes = new java.util.HashSet<>();
            for (int value : nums) {
                prefixes.add(value & mask);
            }

            int candidate = answer | (1 << bit);
            for (int prefix : prefixes) {
                if (prefixes.contains(prefix ^ candidate)) {
                    answer = candidate;
                    break;
                }
            }
        }

        return answer;
    }
}
```

An empty array is not part of the usual platform constraints, so no special return is needed here. Duplicate values are fine because the set only stores prefixes, not indexes.

Time complexity: `O(31 * n)`. Space complexity: `O(n)` for the prefix set.

A binary trie stores each number from its highest bit to its lowest bit. While checking a number, the code prefers the opposite bit at every level because opposite bits produce `1` in XOR. Higher bits are checked first, so this greedy choice gives the best value for that number.

All numbers are inserted before the queries start. The input array is not changed.

```cpp
class Solution {
private:
    struct Node {
        Node* child[2];

        Node() {
            child[0] = nullptr;
            child[1] = nullptr;
        }
    };

    void insert(Node* root, int value) {
        Node* current = root;

        for (int bit = 30; bit >= 0; --bit) {
            int valueBit = (value >> bit) & 1;
            if (current->child[valueBit] == nullptr) {
                current->child[valueBit] = new Node();
            }
            current = current->child[valueBit];
        }
    }

    int bestXor(Node* root, int value) {
        Node* current = root;
        int result = 0;

        for (int bit = 30; bit >= 0; --bit) {
            int valueBit = (value >> bit) & 1;
            int wanted = 1 - valueBit;

            if (current->child[wanted] != nullptr) {
                result |= (1 << bit);
                current = current->child[wanted];
            } else {
                current = current->child[valueBit];
            }
        }

        return result;
    }

public:
    int findMaximumXOR(vector<int>& nums) {
        Node* root = new Node();

        for (int value : nums) {
            insert(root, value);
        }

        int answer = 0;
        for (int value : nums) {
            answer = max(answer, bestXor(root, value));
        }

        return answer;
    }
};
```

For example, with `[3, 10, 5, 25, 2, 8]`, checking `5` tries to match its `0` bits with `1` bits first. The trie finds `25`, giving `5 ^ 25 = 28`.

Time complexity: `O(31 * n)`, which is usually written as `O(n)` because the bit count is fixed. Space complexity: `O(31 * n)` for the trie.

